/** Classify only explicitly entered CPR facts; do not invent missing s/d/a. */
export function fireCprState(cpr:string):"critical"|"open"|"recorded" {
  const value=cpr.trim().toLowerCase().replace(/\s/g,"");
  if(value==="aca")return "recorded";
  if(/^(?:eca|fca)(?:-|$)/.test(value))return "critical";
  if(!/^(?:b1ca|b2ca|cca|dca)(?:-|$)/.test(value))return "open";
  const extra=value.slice(value.indexOf('-')+1),parts=extra.split(',');
  if(parts.includes('s3')||parts.includes('d2')||parts.includes('a3'))return "critical";
  if(!parts.some(p=>/^s(?:1a|1b|1|2)$/.test(p))||!parts.some(p=>/^d[01]$/.test(p))||!parts.some(p=>/^a[12]$/.test(p)))return "open";
  return "recorded";
}

export function fireCableFact(id:string):FireCableFact {
  const fact=FIRE_CABLE_FACTS.find(item=>item.id===id);
  if(!fact)throw new Error("Kabel ist im datierten Referenzkatalog nicht vorhanden.");
  return fact;
}

/** Source-labelled numeric selection; project confirmation is deliberately separate. */
export function fireCableSelection(id:string,supplier="") {
  const fact=fireCableFact(id),selected=supplier?fact.suppliers.find(item=>item.supplier===supplier):undefined;
  if(supplier&&!selected)throw new Error("Für diesen Lieferanten ist kein plausibler Quellenwert hinterlegt.");
  const mj=selected?.mj??fact.mj;
  return {
    catalogId:id,supplier,cpr:fact.cpr,
    name:`${fact.label} · ${fact.cpr||'CPR offen'}${selected?` · ${selected.supplier} ${selected.article}`:''}${fact.basis==='richtwert'&&!selected?' · ca.-Richtwert':''}`,
    mjPerMeter:String(mj),evidence:fireCprState(fact.cpr)==='critical'?'critical' as const:'open' as const,
  };
}
